def head(title,desc):return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} — Folco Soffietti</title><meta name="description" content="{esc(desc,quote=True)}"><meta name="theme-color" content="#ffffff"><link rel="icon" href="{favicon}"><link rel="stylesheet" href="/style.css"><script src="/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="/" aria-label="Folco Soffietti, home">Folco<span> S.</span></a><p class="header-note">Design, research & the making of things</p><nav class="top-nav" aria-label="Main navigation"><a href="/#work">Work</a><a href="/#about">About</a><a href="/#contact">Contact</a></nav></header>'''
