def foot():return '''<footer class="contact wrap" id="contact"><div class="contact-top"><p class="eyebrow">Have something in mind?</p><img class="contact-hand" src="/assets/hand-open.webp" alt="" loading="lazy"></div><h2 class="reveal">Let’s make<br><em>something matter.</em></h2><a class="email" href="mailto:folco.soffietti@gmail.com" data-cursor="Say hello">folco.soffietti@gmail.com</a><div class="contact-bottom"><span>© Folco Soffietti · Design & art</span><span>We can talk in English, italiano or français.</span><a href="#" class="text-link">Back to top ↑</a></div></footer>'''+cursor()+'''</body></html>'''
