home=head('Design & art','An artisan’s approach to information design, illustration and sculpture. The portfolio of Folco Soffietti.')+'''<main id="main"><section class="hero wrap"><h1 class="name reveal">Folco <span class="surname">Soffietti</span></h1><div class="hero-main"><div class="hero-copy"><h2 class="reveal">A narrative <em>artisan.</em></h2></div><nav class="orbit" aria-label="Explore my practice"><div class="landscape-drag" tabindex="0" role="group" aria-label="Move the landscape with the arrow keys. Press Home to reset." data-cursor="Grab"><img class="orbit-image" src="/assets/landscape.webp" alt="My hand-drawn landscape, with a path connecting the surrounding buildings" fetchpriority="high" draggable="false"></div><a class="o1" href="#information"><span>01 / MAKING SENSE</span>Information<br>Design</a><a class="o2" href="#creative"><span>02 / TELLING STORIES</span>Creative<br>Design</a><a class="o3" href="#personal"><span>03 / KEEPING CURIOUS</span>Personal<br>practice</a></nav><div class="landscape-controls"><span>Pick up the landscape and move it.</span><button type="button" data-reset-landscape>Reset position ↺</button></div></div><div class="hero-foot"><span>RESEARCH INFORMS. HANDS EXPLORE.</span><a class="down" href="#about">SCROLL TO EXPLORE <i aria-hidden="true">↓</i></a></div></section><section class="about wrap" id="about"><p class="eyebrow">A way of working</p><div class="about-text"><p class="statement reveal">Different tools.<br>The same attention to <em>what matters.</em></p><div class="about-detail"><p>I think of myself as a narrative artisan. Whether creating a diagram, a digital interface, a graphic novel or a sculpture, the medium follows the questions and the story they trigger.</p><p>My research experience at Università Iuav di Venezia shapes an approach grounded in careful observation, clear communication and a willingness to experiment.</p></div></div></section><section class="wrap" id="work"><div class="work-heading"><h2 class="reveal">Selected <em>work.</em></h2><p class="eyebrow">Three connected practices / 01—03</p></div><div class="work-layout"><aside class="shared-view" aria-label="Project preview"><a href="/work/medigreen/" id="preview-link" data-cursor="View work"><div class="image-stage"><img src="/assets/posters-02.webp" alt="MEDIGREEN campaign poster" class="active"><img alt=""></div></a><div class="image-caption"><span id="preview-title">MEDIGREEN</span><span id="preview-kind">Visual identity</span></div></aside><div class="chapters">'''
sections=[('information','01','Information Design','Making complex subjects legible and appealing is what motivates my work in information design, data visualisation and visual identities across science, marine sustainability and European projects.','doodle-01.webp'),('creative','02','Creative Design','There is always a story behind. Illustration and comics are great media for bringing scientific and technological subjects closer, through characters, images and a little imagination.','fish.webp'),('personal','03','Personal practice','Making to learn and find balance. Sculpture is an ongoing exploration of material, gesture and form, with room for uncertainty and the pleasure of working by hand. A medium that can be integrated into communication when needed.','posture-study.webp')]
