home+='''</div></div></section><section class="playground" aria-labelledby="gallery-title"><div class="playground-title wrap"><div><p class="eyebrow">A few things from the workbench</p><h2 class="reveal" id="gallery-title">Follow your <em>curiosity.</em></h2></div><div class="gallery-controls"><span class="small">Explore</span><button data-gallery-prev aria-label="Previous artworks">←</button><button data-gallery-next aria-label="Next artworks">→</button></div></div><div class="drag-gallery" tabindex="0" role="region" aria-label="Draggable artwork gallery. Use arrow keys or the previous and next buttons." data-cursor="Grab"><div class="gallery-track">'''
items=[('plastissea','plastissea-17.webp','An underwater story','Illustration'),('sketchbook','doodle-10.webp','Notes in the margins','Drawing'),('medigreen','posters-06.webp','Many uses, one sea','Communication'),('sculpture','diana-4.webp','Learning to look','Sculpture'),('idee','idee-03.webp','Ideas in sequence','Comics'),('mediterranean-in-numbers','numbers-02.webp','Making scale visible','Data'),('sketchbook','doodle-06.webp','A place on paper','Sketchbook')]
for slug,img,title,kind in items:home+=f'<a class="gallery-item" href="/work/{slug}/" data-cursor="Grab / open" draggable="false"><figure><img src="{A(img)}" alt="{esc(title)}" loading="lazy" draggable="false"><figcaption>{title}<span>{kind}</span></figcaption></figure></a>'
home+='</div></div><p class="gallery-hint wrap">Drag to explore, use the arrows, or open a work to take a closer look.</p></section></main>'+foot();(OUT/'index.html').write_text(home)
for n,p in enumerate(projects):
 category_id=next(s[0] for s in sections if s[2]==p['category'])
 content=head(p['title'],p['description'])+f'''<main id="main"><section class="project-head wrap"><div class="breadcrumb"><a href="/#{category_id}">← {esc(p['category'])}</a><span>{n+1:02d} / {len(projects):02d}</span></div><h1 class="reveal">{esc(p['title'])}</h1><div class="project-intro"><dl class="project-meta"><div><dt>Practice</dt><dd>{esc(p['kind'])}</dd></div></dl><div><p class="project-description reveal">{esc(p['description'])}</p><p class="project-note">{esc(p['note'])}</p>'''

 content+='</div></div></section><section class="project-gallery wrap" aria-label="Project images">'
 if p['slug']=='aquaculture':
  content += '<div class="embedded-project wide"><iframe src="https://fsoff.github.io/Aquaculture-fr/" title="Filière Aquacole: explore the stages of the aquaculture sector" loading="eager" referrerpolicy="strict-origin-when-cross-origin"></iframe></div>'
 if p['slug']=='sculpture':
  content += '<div class="model-section wide"><h2>Resting Diana <em>(Maria)</em></h2><div class="model-viewer" data-model-viewer data-cursor="Rotate" tabindex="0" role="group" aria-label="Interactive sculpture. Use arrow keys to rotate and plus or minus to zoom."><img class="model-fallback" src="/assets/diana-4.webp" alt="Resting Diana, static view"><p class="model-status" role="status">Loading the sculpture…</p></div><div class="model-controls"><button data-model-left aria-label="Rotate sculpture left">← Rotate</button><button data-model-right aria-label="Rotate sculpture right">Rotate →</button><button data-model-zoom-in aria-label="Zoom in">+</button><button data-model-zoom-out aria-label="Zoom out">−</button><button data-model-reset>Reset view ↺</button></div><p class="viewer-hint">Drag to turn. Scroll or pinch to zoom. You can also use the buttons or keyboard.</p></div><script type="module" src="/sculpture.js"></script>'
 if p['slug']=='clay-study':
  frames=[A(f'turntable-{i:02d}.webp') for i in range(1,17)]
  content+=f'''<div class="turntable-section wide"><div class="turntable" data-turntable data-frames='{json.dumps(frames)}' data-cursor="Turn" tabindex="0" role="group" aria-label="Photographic sculpture turntable. Drag horizontally or use the arrow keys."><img src="{frames[0]}" alt="Clay sculpture, view 1 of 16" draggable="false"></div><div class="turntable-controls"><button data-turn-prev aria-label="Previous sculpture view">←</button><label>Turn the sculpture<input type="range" min="0" max="15" value="0" step="1" data-turn-range aria-label="Sculpture viewing angle"></label><button data-turn-next aria-label="Next sculpture view">→</button><span data-turn-count role="status">01 / 16</span></div><p class="viewer-hint">Drag horizontally to move through 16 studio photographs.</p></div>'''

 for i,item in enumerate(p['images']):
  file,cap=item[:2];cl=item[2] if len(item)>2 else ''
  content+=f'<figure class="{cl}"><button class="image-open" aria-label="Enlarge: {esc(cap,quote=True)}" data-cursor="Enlarge"><img src="{A(file)}" alt="{esc(cap,quote=True)}" loading="{"eager" if i==0 else "lazy"}"></button><figcaption>{esc(cap)}</figcaption></figure>'
 if 'video'in p:content+=f'<figure class="wide"><video class="project-video" controls playsinline preload="none" poster="/assets/film-poster.webp" aria-label="Drawing in motion"><source src="{A(p["video"])}" type="video/mp4">Your browser does not support video. <a href="{A(p["video"])}">Open the film</a>.</video><figcaption>Drawing in motion. A moving exploration of the supplied artwork.</figcaption></figure>'
 if 'reader'in p:
  r=p['reader'];pages=[A(f'{r["prefix"]}-{i:02d}.webp') for i in range(1,r['count']+1)]
  content+=f'''<div class="reader" data-reader data-pages='{json.dumps(pages)}' data-title="{esc(p['title'],quote=True)}" tabindex="0" aria-label="{esc(r['title'])}"><h2 style="font-size:40px;margin:35px 0 25px">{esc(r['title'])}</h2><div class="reader-toolbar"><button data-prev aria-label="Previous page">← Previous</button><span class="reader-progress" role="status" aria-live="polite">01 / {r['count']}</span><button data-next aria-label="Next page">Next →</button></div><img src="{pages[0]}" alt="{esc(p['title'])}, page 1" loading="lazy"><p class="reader-help">Use the buttons or the left and right arrow keys to turn the pages.</p></div>'''
 np=projects[(n+1)%len(projects)]
